-- Reviewed source records are imported atomically without inferring fulfilments or ordering.
CREATE TABLE booking_import_batches(id TEXT PRIMARY KEY,request_key TEXT NOT NULL UNIQUE,rows_json TEXT NOT NULL CHECK(json_valid(rows_json) AND json_type(rows_json)='array'),created_by TEXT NOT NULL REFERENCES "user"(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE booking_import_refs(source_ref TEXT PRIMARY KEY NOT NULL,booking_id TEXT NOT NULL UNIQUE REFERENCES credit_bookings(id),batch_id TEXT NOT NULL REFERENCES booking_import_batches(id));
CREATE TRIGGER booking_import_validate BEFORE INSERT ON booking_import_batches BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') THEN RAISE(ABORT,'unauthorized') END;
 SELECT CASE WHEN json_array_length(NEW.rows_json) NOT BETWEEN 1 AND 100 THEN RAISE(ABORT,'invalid batch') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r WHERE json_type(r.value,'$.id') IS NOT 'text' OR length(json_extract(r.value,'$.id')) NOT BETWEEN 1 AND 128 OR json_type(r.value,'$.sourceRef') IS NOT 'text' OR length(trim(json_extract(r.value,'$.sourceRef'))) NOT BETWEEN 1 AND 128 OR json_extract(r.value,'$.sourceRef') IS NOT trim(json_extract(r.value,'$.sourceRef')) OR json_type(r.value,'$.requestedMinor') IS NOT 'text' OR json_extract(r.value,'$.requestedMinor') GLOB '*[^0-9]*' OR length(json_extract(r.value,'$.requestedMinor')) NOT BETWEEN 1 AND 16 OR CAST(json_extract(r.value,'$.requestedMinor') AS INTEGER) NOT BETWEEN 1 AND 9007199254740991 OR CAST(CAST(json_extract(r.value,'$.requestedMinor') AS INTEGER) AS TEXT) IS NOT json_extract(r.value,'$.requestedMinor') OR json_type(r.value,'$.currency') IS NOT 'text' OR length(json_extract(r.value,'$.currency'))<>3 OR json_extract(r.value,'$.currency') NOT GLOB '[A-Z][A-Z][A-Z]' OR json_type(r.value,'$.requestedDate') IS NOT 'text' OR date(json_extract(r.value,'$.requestedDate'),'+0 days') IS NOT json_extract(r.value,'$.requestedDate') OR json_extract(r.value,'$.status') NOT IN ('waiting','held','closed','cancelled') OR json_type(r.value,'$.status') IS NOT 'text' OR (json_type(r.value,'$.notes') IS NOT 'null' AND (json_type(r.value,'$.notes') IS NOT 'text' OR length(trim(json_extract(r.value,'$.notes'))) NOT BETWEEN 1 AND 2000))) THEN RAISE(ABORT,'invalid booking') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r GROUP BY json_extract(r.value,'$.sourceRef') HAVING count(*)>1) OR EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r JOIN booking_import_refs x ON x.source_ref=json_extract(r.value,'$.sourceRef')) THEN RAISE(ABORT,'source reference conflict') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r WHERE NOT EXISTS(SELECT 1 FROM members m WHERE m.id=json_extract(r.value,'$.memberId') AND m.member_number=json_extract(r.value,'$.memberNumber') AND m.full_name=json_extract(r.value,'$.memberName') AND m.status='active')) THEN RAISE(ABORT,'member changed or unavailable') END;
END;
CREATE TRIGGER booking_import_apply AFTER INSERT ON booking_import_batches BEGIN
 INSERT INTO credit_bookings(id,member_id,requested_minor,currency,requested_date,status,notes,created_by) SELECT json_extract(r.value,'$.id'),json_extract(r.value,'$.memberId'),CAST(json_extract(r.value,'$.requestedMinor') AS INTEGER),json_extract(r.value,'$.currency'),json_extract(r.value,'$.requestedDate'),json_extract(r.value,'$.status'),json_extract(r.value,'$.notes'),NEW.created_by FROM json_each(NEW.rows_json) r;
 INSERT INTO booking_import_refs(source_ref,booking_id,batch_id) SELECT json_extract(r.value,'$.sourceRef'),json_extract(r.value,'$.id'),NEW.id FROM json_each(NEW.rows_json) r;
END;
CREATE TRIGGER booking_import_no_update BEFORE UPDATE ON booking_import_batches BEGIN SELECT RAISE(ABORT,'import history immutable'); END;
CREATE TRIGGER booking_import_no_delete BEFORE DELETE ON booking_import_batches BEGIN SELECT RAISE(ABORT,'import history immutable'); END;
CREATE TRIGGER booking_import_refs_no_update BEFORE UPDATE ON booking_import_refs BEGIN SELECT RAISE(ABORT,'import references immutable'); END;
CREATE TRIGGER booking_import_refs_no_delete BEFORE DELETE ON booking_import_refs BEGIN SELECT RAISE(ABORT,'import references immutable'); END;
